/bin/bash -lc "python - <<'PY'
import json, os, urllib.request, urllib.parse
icj='a0800368191f3e9a'
with open(os.environ['GALAXY_API_KEY_FILE']) as f: key=f.read().strip()
urls=[f'https://usegalaxy.org/api/implicit_collection_jobs/{icj}',f'https://usegalaxy.org/api/implicit_collection_jobs/{icj}/jobs',f'https://usegalaxy.org/api/jobs?implicit_collection_jobs_id={icj}']
for url in urls:
 try:
  req=urllib.request.Request(url,headers={'x-api-key':key})
  with urllib.request.urlopen(req,timeout=120) as resp: x=json.load(resp)
  print(url.split('/api/')[1],'type',type(x).__name__,'len',len(x) if isinstance(x,list) else len(x.keys()))
  if isinstance(x,dict): print('keys',','.join(sorted(x.keys())))
  elif x: print('keys',','.join(sorted(x[0].keys())))
 except Exception as e: print(url.split('/api/')[1],type(e).__name__,str(e))
PY"

